"""Topology schema.

The topology is an *engineering* description of the plant: what exists, how it is
connected and where each fact comes from.  It deliberately contains no drawing
coordinates; layout is computed later (``layout.py``) and never written back.

Identifier policy
-----------------
* ``id``      – schematic identifier used inside the workflow (``eq.well_pump_a``).
* ``tag``     – real engineering tag (``P-030``) or ``None`` when the source gives none.
* ``tag_status`` – ``source`` (taken from the specification), ``proposed`` (generated by a
  rule, pending review) or ``none``.
* Nozzle ``name`` is a schematic port name; ``number`` is the real nozzle number
  and stays ``None`` until the source provides it.
"""

from __future__ import annotations

from typing import Any, Literal

from pydantic import BaseModel, ConfigDict, Field

SCHEMA_VERSION = "1.0"

ReviewStatus = Literal["pending_review", "approved", "rejected"]
TagStatus = Literal["source", "proposed", "none"]
Lifecycle = Literal["existing", "new", "future", "modified", "unspecified"]


class _Model(BaseModel):
    model_config = ConfigDict(extra="forbid")


class Provenance(_Model):
    """Where a fact comes from.

    Source objects carry ``document``/``page``/``section``; generated objects carry
    ``rule``/``triggers``/``explanation`` and a review ``status``.
    """

    origin: Literal["source", "generated"]
    # --- source facts
    document: str | None = None
    page: int | None = None
    section: str | None = None
    quote: str | None = None
    basis: Literal["explicit", "interpreted", "structural"] | None = None
    note: str | None = None
    # --- generated facts
    rule: str | None = None
    triggers: list[str] = Field(default_factory=list)
    explanation: str | None = None
    status: ReviewStatus | None = None


class Attr(_Model):
    """A value with an optional unit and its own provenance."""

    value: Any
    unit: str | None = None
    provenance: Provenance | None = None


class Ref(_Model):
    """Reference to a connection point: an equipment nozzle, a component port or a boundary."""

    ref: str
    port: str


class _Obj(_Model):
    id: str
    name: str | None = None
    provenance: Provenance
    attributes: dict[str, Attr] = Field(default_factory=dict)


class Area(_Model):
    id: str
    name: str
    description: str | None = None
    provenance: Provenance


class Nozzle(_Model):
    name: str  # schematic port name, unique within the equipment
    role: str  # suction, discharge, inlet, outlet, vent, drain, level_tap, ...
    number: str | None = None  # real nozzle number (never invented)
    size: Attr | None = None  # nominal size, None when unknown
    service: str | None = None
    provenance: Provenance | None = None  # set when the nozzle itself is a proposed addition


class Equipment(_Obj):
    tag: str | None = None
    tag_status: TagStatus = "none"
    model_class: str  # pyDEXPI class name
    area: str
    lifecycle: Lifecycle = "unspecified"
    symbol: str | None = None  # drawing symbol when the DEXPI class is generic (e.g. 'heat_pump'); see catalog.py
    nozzles: list[Nozzle] = Field(default_factory=list)


class Component(_Obj):
    """Inline piping component: valve, check valve, manifold (tee/header), ..."""

    kind: Literal["valve", "check_valve", "manifold", "strainer", "relief"]
    model_class: str
    function: str | None = None  # isolation, check, bypass, drain, vent, control, purge
    technology: str | None = None  # specific valve technology, None when unknown
    technology_status: Literal["specified", "unspecified_generic"] = "specified"
    operation: Literal["manual", "automated", "unknown"] = "unknown"
    tag: str | None = None
    tag_status: TagStatus = "none"
    area: str | None = None
    lifecycle: Lifecycle = "unspecified"
    open_end: Literal["drain", "vent", "relief"] | None = None  # valve discharging to atmosphere/drain
    # manifold only
    role: Literal["split", "merge"] | None = None
    branches: int | None = None


class Boundary(_Obj):
    """Battery limit / off-page connection for a process stream."""

    direction: Literal["in", "out"]
    service: str | None = None
    area: str | None = None


class Instrument(_Obj):
    tag: str | None = None
    tag_status: TagStatus = "none"
    isa_code: str  # PT, TT, LT, PIC, ...
    measured_variable: str  # pressure, temperature, level
    function: Literal["transmitter", "controller", "indicator"]
    loop_id: str | None = None
    # where the instrument senses: {"kind": "line"|"equipment", "ref": id, "port": optional}
    target: dict[str, str] | None = None
    area: str | None = None


class ProcessLine(_Obj):
    service: str
    from_: Ref = Field(alias="from")
    to: Ref
    logical_line: str | None = None  # survives splitting; defaults to ``id``
    split_from: str | None = None
    line_number: str | None = None
    line_number_status: TagStatus = "none"
    header: bool = False
    properties: dict[str, Attr] = Field(default_factory=dict)

    model_config = ConfigDict(extra="forbid", populate_by_name=True)


class Signal(_Obj):
    kind: Literal["measurement", "control"]
    from_: str = Field(alias="from")
    to: str
    loop_id: str | None = None

    model_config = ConfigDict(extra="forbid", populate_by_name=True)


class ControlRequirement(_Obj):
    """A control requirement stated by the source (not yet an instrumented loop)."""

    description: str
    controlled_variable: str | None = None
    measured_at_line: str | None = None  # logical line id
    final_element: str | None = None  # component id
    setpoint: Attr | None = None
    controller_required: bool = False  # True only when the source states automatic control
    action: str | None = None


class ControlLoop(_Obj):
    variable: str
    measurement: str
    controller: str
    final_element: str
    setpoint: Attr | None = None
    requirement: str | None = None


class ModeRequirement(_Model):
    action: Literal["isolate", "discharge", "operate", "note"]
    targets: list[Ref] = Field(default_factory=list)
    text: str


class OperatingMode(_Obj):
    description: str
    requirements: list[ModeRequirement] = Field(default_factory=list)


class Unresolved(_Obj):
    category: Literal["missing_value", "ambiguity", "conflict", "selection", "scope"]
    description: str
    affects: list[str] = Field(default_factory=list)
    needed_for: str | None = None
    question: str | None = None
    status: Literal["open", "resolved"] = "open"


class Modification(_Model):
    """A change proposed to an existing (source) object; the source value is preserved here."""

    id: str
    object_id: str
    field: str
    old: Any = None
    new: Any = None
    provenance: Provenance


class Metadata(_Model):
    drawing_id: str
    title: str
    project: str
    revision: str = "A"
    language: str = "en"
    source_documents: list[dict[str, Any]] = Field(default_factory=list)
    engineering_basis: list[dict[str, Any]] = Field(default_factory=list)
    source_snapshot_sha256: str | None = None  # set on the working topology


class Topology(_Model):
    schema_version: str = SCHEMA_VERSION
    metadata: Metadata
    areas: list[Area] = Field(default_factory=list)
    equipment: list[Equipment] = Field(default_factory=list)
    components: list[Component] = Field(default_factory=list)
    boundaries: list[Boundary] = Field(default_factory=list)
    instruments: list[Instrument] = Field(default_factory=list)
    process_lines: list[ProcessLine] = Field(default_factory=list)
    signals: list[Signal] = Field(default_factory=list)
    control_requirements: list[ControlRequirement] = Field(default_factory=list)
    control_loops: list[ControlLoop] = Field(default_factory=list)
    operating_modes: list[OperatingMode] = Field(default_factory=list)
    unresolved_requirements: list[Unresolved] = Field(default_factory=list)
    modifications: list[Modification] = Field(default_factory=list)

    # ------------------------------------------------------------------ helpers
    def objects(self) -> dict[str, Any]:
        """Every identified object by id (areas excluded)."""
        out: dict[str, Any] = {}
        for coll in (
            self.equipment,
            self.components,
            self.boundaries,
            self.instruments,
            self.process_lines,
            self.signals,
            self.control_requirements,
            self.control_loops,
            self.operating_modes,
        ):
            for o in coll:
                out[o.id] = o
        return out

    def connectable(self) -> dict[str, Any]:
        """Objects that own connection points (equipment, components, boundaries)."""
        out: dict[str, Any] = {}
        for coll in (self.equipment, self.components, self.boundaries):
            for o in coll:
                out[o.id] = o
        return out


def ports_of(obj: Any) -> list[str]:
    """Names of the connection points of an equipment, component or boundary."""
    if isinstance(obj, Equipment):
        return [n.name for n in obj.nozzles]
    if isinstance(obj, Boundary):
        return ["port"]
    if isinstance(obj, Component):
        if obj.kind == "manifold":
            return ["common"] + [f"b{i}" for i in range(1, (obj.branches or 0) + 1)]
        return ["in", "out"]
    raise TypeError(f"{type(obj).__name__} has no ports")


def logical(line: ProcessLine) -> str:
    return line.logical_line or line.id


def source_prov(
    document: str,
    page: int,
    section: str,
    *,
    quote: str | None = None,
    basis: str = "explicit",
    note: str | None = None,
) -> Provenance:
    return Provenance(
        origin="source",
        document=document,
        page=page,
        section=section,
        quote=quote,
        basis=basis,  # type: ignore[arg-type]
        note=note,
    )


def generated_prov(
    rule: str, triggers: list[str], explanation: str, status: ReviewStatus = "pending_review"
) -> Provenance:
    return Provenance(
        origin="generated", rule=rule, triggers=triggers, explanation=explanation, status=status
    )


def is_pending(p: Provenance) -> bool:
    """True for generated objects that no engineering review has approved yet."""
    return p.origin == "generated" and p.status != "approved"
